// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));

        // Call setOwner using any caller (default is test contract, not admin)
        // The reference will revert because caller is not admin;
        // we handle the revert and check that owner remained unchanged.

        address ownerBefore = c.owner();
        bool reverted;

        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // If the call succeeded, owner must equal newOwner
            assertTrue(c.owner() == newOwner, "Owner should be newOwner after successful setOwner");
        } else {
            // If the call reverted, owner must remain unchanged
            assertTrue(c.owner() == ownerBefore, "Owner should remain unchanged after revert");
        }
    }
}

